 Context context;Vault other,third;String peer,me,username,thirdName,gid;
 void local(Repository.Job<Boolean> job)throws Exception{CountDownLatch done=new CountDownLatch(1);Throwable[] error={null};Repository.local(context,v->{try{return job.run(v);}catch(Throwable e){error[0]=e;return false;}},ok->done.countDown(),m->{error[0]=new AssertionError(m);done.countDown();});assertTrue(done.await(45,TimeUnit.SECONDS));if(error[0]!=null)throw new AssertionError(error[0]);}
 @Before public void setup()throws Exception{Assume.assumeTrue("yes".equals(InstrumentationRegistry.getArguments().getString("groups")));context=ApplicationProvider.getApplicationContext();assertTrue(BuildConfig.ALLOW_TEST_DEVICES);assertTrue(BuildConfig.BACKEND_URL.startsWith("http://10.0.2.2:"));context.getSharedPreferences("notification_access",0).edit().putBoolean("asked",true).commit();Repository.reset();other=new Vault(context,"feature10_"+UUID.randomUUID());gid=UUID.randomUUID().toString();local(v->{if(v.account()!=null)throw new SecurityException("Disposable installation required");Session.continueAccount(v,"qa_ui_"+UUID.randomUUID().toString().substring(0,8),"Modern-Test-2026!");me=Session.uid();username="qa_ui_"+UUID.randomUUID().toString().substring(0,8);Session.continueAccount(other,username,"Modern-Test-2026!");peer=Session.uid();TestIdentityTrust.pin(other,Repository.lookup(other,v.account().getString("username")));Session.restore(v);TestIdentityTrust.pin(v,Repository.lookup(v,username));Repository.send(v,peer,"Contact request");Repository.sync(v);Session.restore(other);Repository.sync(other);Repository.approveContact(other,me);other.clearHistory(me);Session.restore(v);Repository.sync(v);v.clearHistory(peer);return true;});}
 @After public void cleanup()throws Exception{if(other==null)return;InstrumentationRegistry.getInstrumentation().runOnMainSync(()->{for(Activity a:new ArrayList<>(ActivityLifecycleMonitorRegistry.getInstance().getActivitiesInStage(Stage.RESUMED)))a.finish();});InstrumentationRegistry.getInstrumentation().waitForIdleSync();local(v->{if(third!=null){Session.restore(third);Session.resetAccount(third);}Session.restore(other);Session.resetAccount(other);Session.restore(v);Session.resetAccount(v);Repository.eraseLocal(v);return true;});if(third!=null)third.destroy();other.destroy();Repository.reset();}
 @Test public void groupsCombineRequestsWithChatsAndDeclineIsExplicit()throws Exception{String invite=UUID.randomUUID().toString();local(v->{Session.restore(other);GroupRepository.create(other,gid,"A private invitation");GroupRepository.action(other,"inviteGroupMember",new JSONObject().put("groupId",gid).put("uid",me).put("id",invite));Session.restore(v);Repository.sync(v);return true;});try(ActivityScenario<InboxActivity> s=ActivityScenario.launch(InboxActivity.class)){await(s,a->find(a.root,"Groups · 1")!=null,"request badge");s.onActivity(a->{View chats=description(a.root,"All chats"),groups=description(a.root,"Groups. 1 requests"),settings=description(a.root,"Settings");int[] cp=new int[2],gp=new int[2],sp=new int[2];chats.getLocationOnScreen(cp);groups.getLocationOnScreen(gp);settings.getLocationOnScreen(sp);assertTrue("Bottom navigation must read All chats, Groups, Settings",cp[0]<gp[0]&&gp[0]<sp[0]);assertNull(find(a.root,"A private invitation"));tap(find(a.root,"Groups · 1"));});await(s,a->find(a.root,"Accept")!=null,"request card");s.onActivity(a->{assertNotNull(find(a.root,"Decline"));tap(find(a.root,"Decline"));});await(s,a->find(a.root,"Accept")==null,"decline refresh");local(v->{assertEquals(0,v.groupInvites().length());assertTrue(v.groups().isEmpty());return true;});}}
 @Test public void memberPickerFindsSavedContactsAndDirectoryWithoutJoiningThem()throws Exception{third=new Vault(context,"feature10_directory_"+UUID.randomUUID());thirdName="qa_dir_"+UUID.randomUUID().toString().substring(0,8);local(v->{Session.continueAccount(third,thirdName,"Modern-Test-2026!");Session.restore(v);GroupRepository.create(v,gid,"Pick people");Repository.sync(v);return true;});try(ActivityScenario<GroupDetailsActivity> s=ActivityScenario.launch(new Intent(context,GroupDetailsActivity.class).putExtra("group",gid))){await(s,a->find(a.root,"Add members")!=null);s.onActivity(a->tap(find(a.root,"Add members")));awaitDialogText("@"+username);assertNull(activeText("@"+thirdName));setDialogSearch(thirdName);awaitDialogText("@"+thirdName);clickActive("@"+thirdName);awaitDialogText("Invite @"+thirdName+"?");s.onActivity(a->groupDialog(a).getButton(-1).performClick());local(v->{Session.restore(third);Repository.sync(third);Session.restore(v);return true;});for(int wait=0;wait<50;wait++){boolean[] invited={false};local(v->{Session.restore(third);Repository.sync(third);invited[0]=third.groupInvites().length()==1;Session.restore(v);return true;});if(invited[0])break;SystemClock.sleep(100);}local(v->{assertEquals(1,v.group(gid).getJSONArray("members").length());Session.restore(third);Repository.sync(third);assertEquals(1,third.groupInvites().length());assertTrue(third.groups().isEmpty());Session.restore(v);return true;});}}
 @Test public void soleMemberDeletesInsteadOfLeavingAndHeaderOpensDetails()throws Exception{local(v->{GroupRepository.create(v,gid,"Just me");Repository.sync(v);return true;});try(ActivityScenario<ChatActivity> chat=ActivityScenario.launch(new Intent(context,ChatActivity.class).putExtra("peer","group:"+gid))){await(chat,a->find(a.root,"Just me")!=null);chat.onActivity(a->{assertNull(description(a.root,"Chat details"));tap(find(a.root,"Just me"));});awaitDialogOrActivityText("Delete group");assertNull(activeText("Leave group"));clickActive("Delete group");awaitDialogText("Delete this group?");clickActive("Confirm");for(int i=0;i<100;i++){boolean[] done={false};local(v->{JSONObject g=v.group(gid);done[0]=g!=null&&g.optBoolean("hidden")&&!g.optBoolean("active");return true;});if(done[0])return;SystemClock.sleep(100);}fail("Sole group was not removed");}}
 @Test public void horizontalSwipeRepliesVerticalScrollDoesNotAndReplySurvivesRotation()throws Exception{String[] id={null};local(v->{JSONObject m=TestIdentityTrust.send(v,peer,"Gesture original",null);id[0]=m.getJSONObject("envelope").getString("id");Repository.sync(v);return true;});try(ActivityScenario<ChatActivity> s=ActivityScenario.launch(new Intent(context,ChatActivity.class).putExtra("peer",peer))){await(s,a->find(a.root,"Gesture original")!=null);s.onActivity(a->{gesture(find(a.root,"Gesture original"),0,Ui.dp(a,100));assertNull(description(a.root,"Reply · Gesture original"));gesture(find(a.root,"Gesture original"),Ui.dp(a,110),0);});await(s,a->description(a.root,"Reply · Gesture original")!=null);s.recreate();await(s,a->description(a.root,"Reply · Gesture original")!=null);s.onActivity(a->{((EditText)MessageActionsFlowTest.findComposer(a.root)).setText("Swipe answer");description(a.root,"Send message").performClick();});await(s,a->find(a.root,"Swipe answer")!=null);local(v->{assertEquals(1,v.messages(peer).stream().filter(m->id[0].equals(m.optString("replyTo"))&&"Swipe answer".equals(m.optString("body"))).count());return true;});}}
 @Test public void hyperlinksNeedConfirmationAndLongPressDoesNotOpenThem()throws Exception{String text="Visit https://example.com/path and javascript:alert(1) https://user@example.com https://example.com/"+"x".repeat(2100);local(v->{TestIdentityTrust.send(v,peer,text,null);Repository.sync(v);return true;});try(ActivityScenario<ChatActivity> s=ActivityScenario.launch(new Intent(context,ChatActivity.class).putExtra("peer",peer))){await(s,a->find(a.root,text)!=null);s.onActivity(a->{TextView body=(TextView)find(a.root,text);assertTrue(body.getText() instanceof Spanned);ClickableSpan[] links=((Spanned)body.getText()).getSpans(0,body.length(),ClickableSpan.class);assertEquals(1,links.length);body.performLongClick();assertNotNull(MessageActionsFlowTest.dialog(a));links[0].onClick(body);});assertNull(activeText("Open link?"));s.onActivity(a->{MessageActionsFlowTest.dialog(a).dismiss();TextView body=(TextView)find(a.root,text);((Spanned)body.getText()).getSpans(0,body.length(),ClickableSpan.class)[0].onClick(body);});awaitDialogText("Open link?");clickActive("Cancel");s.moveToState(androidx.lifecycle.Lifecycle.State.CREATED);assertNull(activeText("Open link?"));}}
 @Test public void soleDeleteCannotEraseSomeoneWhoJoinsAtTheSameTime()throws Exception{String invite=UUID.randomUUID().toString();local(v->{GroupRepository.create(v,gid,"A changing group");GroupRepository.action(v,"inviteGroupMember",new JSONObject().put("groupId",gid).put("uid",peer).put("id",invite));Repository.sync(v);return true;});try(ActivityScenario<GroupDetailsActivity> s=ActivityScenario.launch(new Intent(context,GroupDetailsActivity.class).putExtra("group",gid))){await(s,a->find(a.root,"Delete group")!=null);s.onActivity(a->tap(find(a.root,"Delete group")));local(v->{Session.restore(other);GroupRepository.action(other,"acceptGroupInvite",new JSONObject().put("id",invite));Session.restore(v);return true;});s.onActivity(a->groupDialog(a).getButton(-1).performClick());for(int i=0;i<100;i++){boolean[] done={false};local(v->{JSONObject g=v.group(gid);done[0]=g!=null&&g.optBoolean("hidden");return true;});if(done[0])break;SystemClock.sleep(100);}local(v->{Session.restore(other);Repository.sync(other);JSONObject g=other.group(gid);assertNotNull(g);assertTrue(g.getBoolean("active"));assertEquals(1,g.getJSONArray("members").length());assertEquals(peer,g.getJSONArray("members").getJSONObject(0).getString("uid"));Session.restore(v);assertTrue(v.group(gid).optBoolean("hidden"));return true;});}}
 @Test public void inboxSearchKeepsResultsVisibleWithLandscapeKeyboard()throws Exception{shell("settings put secure show_ime_with_hard_keyboard 1");try(ActivityScenario<InboxActivity> s=ActivityScenario.launch(InboxActivity.class)){await(s,a->find(a.root,"@"+username)!=null);s.onActivity(a->a.setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LANDSCAPE));await(s,a->a.getResources().getConfiguration().orientation==android.content.res.Configuration.ORIENTATION_LANDSCAPE&&a.root.isShown());s.onActivity(a->{EditText input=(EditText)MessageActionsFlowTest.findInput(a.root);input.requestFocus();a.getSystemService(android.view.inputmethod.InputMethodManager.class).showSoftInput(input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);});await(s,a->{androidx.core.view.WindowInsetsCompat insets=androidx.core.view.ViewCompat.getRootWindowInsets(a.root);if(insets!=null&&insets.isVisible(androidx.core.view.WindowInsetsCompat.Type.ime()))return true;if(a.hasWindowFocus()){EditText input=(EditText)MessageActionsFlowTest.findInput(a.root);input.requestFocus();a.getSystemService(android.view.inputmethod.InputMethodManager.class).showSoftInput(input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);}return false;},"landscape keyboard");SystemClock.sleep(400);s.onActivity(a->{EditText input=(EditText)MessageActionsFlowTest.findInput(a.root);assertTrue(input.isShown());assertTrue(find(a.root,"@"+username).isShown());assertTrue(find(a.root,"@"+username).getHeight()>0);assertFalse(description(a.root,"Settings").isShown());a.getSystemService(android.view.inputmethod.InputMethodManager.class).hideSoftInputFromWindow(input.getWindowToken(),0);});await(s,a->description(a.root,"Settings").isShown());}finally{shell("settings put secure show_ime_with_hard_keyboard 0");}}
 static void shell(String cmd)throws Exception{try(android.os.ParcelFileDescriptor file=InstrumentationRegistry.getInstrumentation().getUiAutomation().executeShellCommand(cmd);java.io.InputStream input=new android.os.ParcelFileDescriptor.AutoCloseInputStream(file)){while(input.read()!=-1){}}}
 static void dump(View view,StringBuilder text){text.append(view.getClass().getSimpleName()).append(":").append(view.getWidth()).append("x").append(view.getHeight()).append("/").append(view.getVisibility()).append(" ");if(view instanceof TextView)text.append("[").append(((TextView)view).getText()).append("]");if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)dump(((ViewGroup)view).getChildAt(i),text);}
 static void gesture(View target,float dx,float dy){long start=SystemClock.uptimeMillis();float x=target.getWidth()/2f,y=target.getHeight()/2f;for(int i=0;i<=6;i++){MotionEvent event=MotionEvent.obtain(start,start+i*25,i==0?MotionEvent.ACTION_DOWN:i==6?MotionEvent.ACTION_UP:MotionEvent.ACTION_MOVE,x+dx*i/6,y+dy*i/6,0);target.dispatchTouchEvent(event);event.recycle();}}
 interface Ready<T extends Activity>{boolean ok(T a);}static <T extends Activity>void await(ActivityScenario<T> s,Ready<T> r){await(s,r,"screen");}static <T extends Activity>void await(ActivityScenario<T> s,Ready<T> r,String stage){for(int i=0;i<120;i++){boolean[] ok={false};s.onActivity(a->ok[0]=r.ok(a));if(ok[0])return;SystemClock.sleep(100);}StringBuilder dump=new StringBuilder();s.onActivity(a->{dump(a.getWindow().getDecorView(),dump);try{if(a instanceof InboxActivity){for(String name:new String[]{"rows","invites","groupsOnly"}){java.lang.reflect.Field f=InboxActivity.class.getDeclaredField(name);f.setAccessible(true);dump.append(name).append(":").append(f.get(a));}}}catch(Exception e){throw new AssertionError(e);}});fail("Feature UI did not update: "+stage+" "+dump);}
 static View find(View v,String text){return MessageActionsFlowTest.find(v,text);}static View description(View v,String text){return MessageActionsFlowTest.findDescription(v,text);}static void tap(View v){assertNotNull(v);while(!v.isClickable()&&v.getParent() instanceof View)v=(View)v.getParent();assertTrue(v.performClick());}
 static androidx.appcompat.app.AlertDialog groupDialog(GroupDetailsActivity a){try{java.lang.reflect.Field f=GroupDetailsActivity.class.getDeclaredField("dialog");f.setAccessible(true);return (androidx.appcompat.app.AlertDialog)f.get(a);}catch(Exception e){throw new AssertionError(e);}}
 static android.view.accessibility.AccessibilityNodeInfo activeText(String text){android.view.accessibility.AccessibilityNodeInfo root=InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow();if(root==null)return null;for(android.view.accessibility.AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText(text))if(n.getText()!=null&&text.equalsIgnoreCase(n.getText().toString()))return n;return null;}
 static void awaitDialogText(String text){awaitDialogOrActivityText(text);}static void awaitDialogOrActivityText(String text){for(int i=0;i<120;i++){if(activeText(text)!=null)return;SystemClock.sleep(100);}fail("Missing text: "+text);}
 static void clickActive(String text){awaitDialogText(text);android.view.accessibility.AccessibilityNodeInfo node=activeText(text);assertNotNull(text,node);while(!node.isClickable()&&node.getParent()!=null)node=node.getParent();assertTrue(node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK));InstrumentationRegistry.getInstrumentation().waitForIdleSync();}
 static void setDialogSearch(String text){android.view.accessibility.AccessibilityNodeInfo root=InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow();assertNotNull(root);android.view.accessibility.AccessibilityNodeInfo input=findInput(root);assertNotNull(input);android.os.Bundle args=new android.os.Bundle();args.putCharSequence(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,text);assertTrue(input.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SET_TEXT,args));}
 static android.view.accessibility.AccessibilityNodeInfo findInput(android.view.accessibility.AccessibilityNodeInfo n){if("android.widget.EditText".contentEquals(n.getClassName()))return n;for(int i=0;i<n.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo child=n.getChild(i);if(child!=null){android.view.accessibility.AccessibilityNodeInfo found=findInput(child);if(found!=null)return found;}}return null;}
